static Mutex mutext1;

class AThread: public Thread {
public:
 virtual bool threadLoop() {
 Mutex::Autolock _lock(mutext1);
 snprintf(student.name, sizeof(student.name), "xiaoming");
 student.age = 10;
 student.number = 20200101;
 return true;
 }
};

class BThread: public Thread {
public:
