### 1. 单事件注入函数（一切的基础）
```c
static int reportkey(int fd, uint16_t type, uint16_t code, int32_t value) {
    struct input_event event;
    event.type = type;
    event.code = code;
    event.value = value;
    gettimeofday(&event.time, 0);   // 时间戳必须填
    if (write(fd, &event, sizeof(struct input_event)) < 0) {
        LOGE("fd %d report key error %s!\n", fd, strerror(errno));
        return -1;
    }
    return 0;
}
```

### 2. 单点触摸（zk_touch_test）——完整协议序列
```c
int zk_touch_test(const char *dev, int posx, int posy) {
    int fd = open(dev, O_WRONLY);   // 注入用 O_WRONLY 即可
    if (fd < 0) return -1;

    // === 按下 ===
    reportkey(fd, EV_ABS, ABS_X, posx);           // X 坐标
    reportkey(fd, EV_ABS, ABS_Y, posy);           // Y 坐标
    reportkey(fd, EV_ABS, ABS_PRESSURE, 100);     // 压力值
    reportkey(fd, EV_KEY, BTN_TOUCH, 1);          // 触摸按下键
    reportkey(fd, EV_SYN, EV_SYN, EV_SYN);        // ⚠️ SYN 同步，内核才提交这批事件

    // === 抬起 ===
    reportkey(fd, EV_ABS, ABS_PRESSURE, 0);       // 压力归零
    reportkey(fd, EV_KEY, BTN_TOUCH, 0);          // 触摸抬起键
    reportkey(fd, EV_SYN, EV_SYN, EV_SYN);

    close(fd);
    return 0;
}
```
**协议铁律：`ABS_X/Y → ABS_PRESSURE → BTN_TOUCH → EV_SYN`，EV_SYN 必须发，否则内核不提交。**

### 3. 滑动（zk_swipe_test）——逐像素步进
```c
int zk_swipe_test(const char *dev, int x1, int y1, int x2, int y2) {
    int fd = open(dev, O_WRONLY);
    if (fd < 0) return -1;

    // 按下（同点击的 down 序列）
    reportkey(fd, EV_ABS, ABS_X, x1);
    reportkey(fd, EV_ABS, ABS_Y, y1);
    reportkey(fd, EV_ABS, ABS_PRESSURE, 100);
    reportkey(fd, EV_KEY, BTN_TOUCH, 1);
    reportkey(fd, EV_SYN, EV_SYN, EV_SYN);

    // 逐像素移动：每次只动 1 个像素，发坐标后必须跟 EV_SYN
    int step_x = x1 < x2 ? 1 : -1;
    int step_y = y1 < y2 ? 1 : -1;
    while (1) {
        reportkey(fd, EV_ABS, ABS_X, x1);
        reportkey(fd, EV_ABS, ABS_Y, y1);
        reportkey(fd, EV_SYN, EV_SYN, EV_SYN);
        if (x1 != x2) x1 += step_x;
        if (y1 != y2) y1 += step_y;
        if (x1 == x2 && y1 == y2) break;
    }

    // 抬起（同点击的 up 序列）
    reportkey(fd, EV_ABS, ABS_PRESSURE, 0);

    reportkey(fd, EV_KEY, BTN_TOUCH, 0);
    reportkey(fd, EV_SYN, EV_SYN, EV_SYN);

    close(fd);
    return 0;
}
```
- 滑动要点：**逐像素（或中点插值）发中间坐标，不能一次跳终点**（会被识别为无效/抖动）；每步 EV_SYN
- event.c 里还有注释掉的 **ABS_MT_* 多点触控协议示例**（ABS_MT_POSITION_X/Y、ABS_MT_TOUCH_MAJOR + SYN_MT_REPORT），多指手势参考那段

## 如何任意开启停止定时器
我们可以在REGISTER_ACTIVITY_TIMER_TAB中添加预设的定时器，但这种方式不够灵活，无法任意开启/停止，下面介绍另一种添加定时器的方法。 Activity类中有提供三个关于定时器的方法， 下面介绍如何使用。

```c++
/**
 * 注册定时器
 */
void registerUserTimer(int id, int time);
/**
 * 取消定时器
 */
void unregisterUserTimer(int id);
/**
 * 重置定时器
 */
void resetUserTimer(int id, int time);
```

- 在logic.cc中，添加一个变量，标识该定时器是否已经注册。

```c++
/**
 * 是否注册了定时器
 */
static bool isRegistered = false;

#define TIMER_HANDLE 2
```

- 我们再添加两个按键，在按键的点击事件中，我们分别添加 注册定时器、取消定时器的代码。

```c++
static bool onButtonClick_ButtonTimerOn(ZKButton *pButton) {
 //如果没有注册才进行注册定时器
 if (!isRegistered) {
 mActivityPtr->registerUserTimer(TIMER_HANDLE, 500);
 isRegistered = true;
 }
 return false;
}

static bool onButtonClick_ButtonTimerOff(ZKButton *pButton) {
 //如果已经注册了定时器，则取消注册
 if (isRegistered) {
 mActivityPtr->unregisterUserTimer(TIMER_HANDLE);
 isRegistered = false;
 }
 return false;
}
```

重要
以上提到的 registerUserTimer、unregisterUserTimer、resetUserTimer 三个函数不能在 onUI_Timer函数中调用，会造成死锁。

## 如何使用定时器

- 注册定时器 为了方便使用，我们以填充结构体的形式来添加定时器。 在Logic.cc文件中，默认会有这样一个结构体数组：

```c++
/**
 * 注册定时器
 * 在此数组中添加即可
 */
static S_ACTIVITY_TIMEER REGISTER_ACTIVITY_TIMER_TAB[] = {
 //{0, 6000}, //定时器id=0, 时间间隔为6秒
 //{1, 1000},
};
```

如果我们想要添加一个定时器时，只需要在这个数组中添加结构体即可。
 这个结构体的定义如下：

```c++
typedef struct {
 int id; // 定时器ID ， 不能重复
 int time; // 定时器时间间隔 单位/毫秒
}S_ACTIVITY_TIMEER;
```

- 添加定时器的逻辑代码 在数组中注册定时器后，当某一个定时器触发时，系统将调用对应 Logic.cc 文件中的 void onUI_Timer(int id)函数，针对这个定时器的所有操作代码，就是添加在这个函数中，函数具体定义如下：

```c++
/**
 * 定时器触发函数
 * 不建议在此函数中写耗时操作，否则将影响UI刷新
 * @param id
 * 当前所触发定时器的id，与注册时的id相同
 * @return true
 * 继续运行当前定时器
 * false
 * 停止运行当前定时器
 */
static bool onUI_Timer(int id){
 switch (id) {

 default:
 break;
 }
 return true;
}
```

该函数同样是随 Logic.cc 文件默认生成。 注意函数的参数 id ，它与结构体数组中定义的 id 值相同，我们可以根据 id 值判断当前触发的是哪一个定时器，从而做一些针对性的操作。

注意
- 每个界面的定时器都是独立的，不同界面定时器的id可以相同；

